mapper.select:
select u.user_id, u.dept_id, u.login_name, u.user_name, u.user_type, u.email, u.avatar, u.phonenumber, u.password, u.sex, u.salt, u.status,
       u.allow_admin_login, u.allow_mini_login, u.audit_status, u.register_source, u.register_invite_id,
       u.audit_by, u.audit_time, u.audit_remark, u.dispatchable, u.openid, u.union_id, u.wx_bind_time,
       u.del_flag, u.login_ip, u.login_date, u.create_by, u.create_time, u.remark, d.dept_name, d.leader
  from sys_user u
left join sys_dept d on u.dept_id = d.dept_id
where u.del_flag = '0'

	AND u.user_id = #{userId}


	AND u.login_name like concat('%', #{loginName}, '%')


	AND u.status = #{status}


	AND u.phonenumber like concat('%', #{phonenumber}, '%')


	AND u.audit_status = #{auditStatus}


	AND u.register_source = #{registerSource}


	AND u.register_source in

		#{src}



	AND u.dispatchable = #{dispatchable}


	AND date_format(u.create_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')


	AND date_format(u.create_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')


	AND (u.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE FIND_IN_SET (#{deptId},ancestors) ))


${params.dataScope}

select distinct u.user_id, u.dept_id, u.login_name, u.user_name, u.user_type, u.email, u.avatar, u.phonenumber, u.status, u.create_time from sys_user u left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0' and r.role_id = #{roleId}
AND u.login_name like concat('%', #{loginName}, '%')
AND u.phonenumber like concat('%', #{phonenumber}, '%')
${params.dataScope}

mapper.update:
update sys_user
dept_id = #{deptId}, user_name = #{userName}, user_type = #{userType}, email = #{email}, phonenumber = #{phonenumber}, sex = #{sex}, avatar = #{avatar}, password = #{password}, salt = #{salt}, status = #{status}, allow_admin_login = #{allowAdminLogin}, allow_mini_login = #{allowMiniLogin}, audit_status = #{auditStatus}, register_source = #{registerSource}, register_invite_id = #{registerInviteId}, audit_by = #{auditBy}, audit_time = #{auditTime}, audit_remark = #{auditRemark}, dispatchable = #{dispatchable}, openid = #{openid}, union_id = #{unionId}, wx_bind_time = #{wxBindTime}, login_ip = #{loginIp}, login_date = #{loginDate}, pwd_update_date = #{pwdUpdateDate}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where user_id = #{userId}
